from pyspark.sql import functions as F
from pyspark.errors import PySparkException

feed = spark.createDataFrame(
    [("E0000101", "SH0002"), ("E00001O2", "SH0003"), (None, "SH0004")],
    "event_id STRING, shipment_id STRING",
)


def numbered():
    return feed.select("event_id", F.substring("event_id", 2, 20).cast("int").alias("event_no"))


def attempt(name, build, action):
    try:
        df = build()
    except PySparkException as e:
        print(name, "build", e.getCondition())
        return
    try:
        print(name, "ok", action(df))
    except PySparkException as e:
        print(name, "action", e.getCondition())


attempt("A", lambda: feed.select("event_id", "shipment"), lambda df: df.count())
attempt("B", numbered, lambda df: df.count())
attempt("C", numbered, lambda df: df.filter(F.col("event_id").isNull()).count())
attempt("D", numbered, lambda df: df.filter(F.col("event_no") > 100).count())
